import{_ as a,o as e,c as o,aw as n}from"./chunks/framework.DLufY-ao.js";const A=JSON.parse('{"title":"Web Workers","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/js/js/other/web-workers.md","filePath":"wiki/dev-commit/js/js/other/web-workers.md"}'),l={name:"wiki/dev-commit/js/js/other/web-workers.md"};function p(t,s,r,c,i,y){return e(),o("div",null,[...s[0]||(s[0]=[n(`<h1 id="web-workers" tabindex="-1">Web Workers <a class="header-anchor" href="#web-workers" aria-label="Permalink to &quot;Web Workers&quot;">​</a></h1><ul><li>Спецификация Web Workers позволяет запускать дополнительные JavaScript-процессы (workers). Они могут обмениваться сообщениями с главным процессом, но у них свои переменные, и работают они также сами по себе</li><li>Worker - это объект, созданный при помощи конструктора , который запускает JavaScript файл с кодом, который будет выполнен в потоке Worker’а</li><li>Такие дополнительные процессы не имеют доступа к DOM, поэтому они полезны, преимущественно, при вычислениях, чтобы загрузить несколько ядер/процессоров одновременно</li><li>Современные браузеры позволяют порождать подпроцессы Web Workers, они выполняются параллельно и могут отправлять/принимать сообщения, но не имеют доступа к DOM</li></ul><h3 id="_1-создание" tabindex="-1">1. Создание <a class="header-anchor" href="#_1-создание" aria-label="Permalink to &quot;1. Создание&quot;">​</a></h3><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#A626A4;">const</span><span style="color:#986801;"> myWorker</span><span style="color:#0184BC;"> =</span><span style="color:#A626A4;"> new</span><span style="color:#4078F2;"> Worker</span><span style="color:#383A42;">(</span><span style="color:#50A14F;">&quot;worker.js&quot;</span><span style="color:#383A42;">);</span></span></code></pre></div><h3 id="_2-отправка-данных-в-веб-воркер" tabindex="-1">2.Отправка данных в веб-воркер <a class="header-anchor" href="#_2-отправка-данных-в-веб-воркер" aria-label="Permalink to &quot;2.Отправка данных в веб-воркер&quot;">​</a></h3><ul><li>У каждого веб воркера, как и у главного потока, имеется свой stack, heap и event loop. Послать сообщения в веб воркер (например, передать данные для расчетов) можно с помощью метода postMessage()</li></ul><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#383A42;">myWorker.</span><span style="color:#4078F2;">postMessage</span><span style="color:#383A42;">(imageData);</span></span></code></pre></div><h3 id="_3-событие-типа-message" tabindex="-1">3. Событие типа message <a class="header-anchor" href="#_3-событие-типа-message" aria-label="Permalink to &quot;3. Событие типа message&quot;">​</a></h3><ul><li>Это создаст событие типа message в очередь событий web worker’а, которое будет обработано в следующей итерации event loop воркера</li></ul><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#4078F2;">onmessage</span><span style="color:#0184BC;"> =</span><span style="color:#A626A4;"> function</span><span style="color:#383A42;">(e) {</span></span>
<span class="line"><span style="color:#383A42;">	console.</span><span style="color:#4078F2;">log</span><span style="color:#383A42;">(</span><span style="color:#50A14F;">&#39;Message received from main script&#39;</span><span style="color:#383A42;">);</span></span>
<span class="line"><span style="color:#A626A4;">	const</span><span style="color:#986801;"> workerResult</span><span style="color:#0184BC;"> =</span><span style="color:#50A14F;"> &#39;Result: &#39;</span><span style="color:#0184BC;"> +</span><span style="color:#383A42;"> (e.</span><span style="color:#E45649;">data</span><span style="color:#383A42;">[</span><span style="color:#986801;">0</span><span style="color:#383A42;">] </span><span style="color:#0184BC;">*</span><span style="color:#383A42;"> e.</span><span style="color:#E45649;">data</span><span style="color:#383A42;">[</span><span style="color:#986801;">1</span><span style="color:#383A42;">]);</span></span>
<span class="line"><span style="color:#383A42;">	console.</span><span style="color:#4078F2;">log</span><span style="color:#383A42;">(</span><span style="color:#50A14F;">&#39;Posting message back to main script&#39;</span><span style="color:#383A42;">);</span></span>
<span class="line"><span style="color:#4078F2;">	postMessage</span><span style="color:#383A42;">(workerResult);</span></span>
<span class="line"><span style="color:#383A42;">}</span></span></code></pre></div><h3 id="_4-отправка-данных-в-главныи-поток" tabindex="-1">4. Отправка данных в главный поток <a class="header-anchor" href="#_4-отправка-данных-в-главныи-поток" aria-label="Permalink to &quot;4. Отправка данных в главный поток&quot;">​</a></h3><ul><li>Аналогично, результаты вычислений и прочие данные воркер может отправить в главный поток с помощью метода postMessage(). И это опять же добавит событие типа message в очередь события главного потока</li></ul><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#383A42;">myWorker.</span><span style="color:#4078F2;">onmessage</span><span style="color:#0184BC;"> =</span><span style="color:#A626A4;"> function</span><span style="color:#383A42;">(e) {</span></span>
<span class="line"><span style="color:#383A42;">	result.</span><span style="color:#E45649;">textContent</span><span style="color:#0184BC;"> =</span><span style="color:#383A42;"> e.</span><span style="color:#E45649;">data</span><span style="color:#383A42;">;</span></span>
<span class="line"><span style="color:#383A42;">	console.</span><span style="color:#4078F2;">log</span><span style="color:#383A42;">(</span><span style="color:#50A14F;">&#39;Message received from worker&#39;</span><span style="color:#383A42;">);</span></span>
<span class="line"><span style="color:#383A42;">}</span></span></code></pre></div>`,13)])])}const u=a(l,[["render",p]]);export{A as __pageData,u as default};
